AFRAME.registerComponent('panel-input-router',{init(){this.listeners=[];this.nativeGestures=new Map();this.bindSession();const listen=(el,name,fn)=>{el.addEventListener(name,fn,true);this.listeners.push(()=>el.removeEventListener(name,fn,true))};listen(this.el,'triggerdown',e=>{const source=e.target;if(!['leftHand','rightHand'].includes(source?.id))return;const side=source.id==='leftHand'?'left':'right',input=[...(this.el.renderer?.xr?.getSession?.()?.inputSources||[])].find(s=>s.handedness===side);if(input?.hand){e.stopImmediatePropagation();return}const k=key({detail:{cursorEl:source}});if(presses.get(k)?.down){e.stopImmediatePropagation();return}const ray=source.components?.raycaster?.raycaster?.ray;if(!ray)return;let best;const caster=new T.Raycaster(ray.origin,ray.direction,0,20),targets=[...cards,...this.el.querySelectorAll('[data-panel-grip]')];for(const el of targets){if(el.isConnected===false)continue;let shown=true;for(let p=el.object3D;p;p=p.parent)if(!p.visible)shown=false;for(let p=el.__panelOwner?.object3D;p;p=p.parent)if(!p.visible)shown=false;if(!shown)continue;el.object3D.updateWorldMatrix(true,true);const hit=caster.intersectObject(el.object3D,true)[0];if(hit&&(!best||priority(el)>priority(best.el)||priority(el)===priority(best.el)&&hit.distance<best.hit.distance))best={el,hit}}if(!best)return;const r=region(best.el,best.hit),drag=best.el.getAttribute('data-panel-grip')==='true'||r?.drag,press={el:best.el,region:r,generation:best.el.__panelInput?.generation,used:true,down:true,at:performance.now()};presses.set(k,press);if(drag)window.globiquest.panelDraggerFor?.(best.el)?.start(source,null,best.el);else if(r?.draw)this.startDrawing(best.el,best.hit,source);else r?.action?.();hover({el:best.el,intersection:best.hit});e.stopImmediatePropagation();e.preventDefault?.()});listen(this.el,'triggerup',e=>window.GlobiquestPanelInput.release(e.target));listen(this.el,'controllerdisconnected',e=>window.GlobiquestPanelInput.release(e.target));listen(this.el,'enter-vr',()=>this.bindSession());listen(this.el,'exit-vr',()=>{presses.clear();this.nativeGestures.clear()});listen(window,'blur',()=>presses.clear())},bindSession(){const session=this.el.renderer?.xr?.getSession?.();if(session===this.nativeSession)return;this.nativeCleanup?.();this.nativeSession=session;this.nativeGestures?.clear();if(!session)return;const eligible=input=>input&&!input.hand&&['left','right'].includes(input.handedness)&&input.targetRayMode==='tracked-pointer';const start=e=>{if(!eligible(e.inputSource))return;this.nativeGestures.set(e.inputSource,true);this.nativeActivate(e)},end=e=>{if(!eligible(e.inputSource))return;const side=e.inputSource.handedness;pointerTool(this.drawingCanvas)?.up();this.drawingCanvas=null;window.GlobiquestPanelInput.release(document.getElementById(side==='left'?'leftHand':'rightHand'));},select=e=>{if(!eligible(e.inputSource))return;if(!this.nativeGestures.has(e.inputSource)){this.nativeActivate(e);end(e)}this.nativeGestures.delete(e.inputSource)};session.addEventListener('selectstart',start);session.addEventListener('selectend',end);session.addEventListener('select',select);this.nativeCleanup=()=>{session.removeEventListener('selectstart',start);session.removeEventListener('selectend',end);session.removeEventListener('select',select)}},
 startDrawing(el,intersection,source,input=null,eventFrame=null){const canvas=pointerTool(el);if(!canvas)return;this.drawingCanvas=el;const getIntersection=target=>{if(target!==el||el.isConnected===false)return null;let ray=source.components?.raycaster?.raycaster?.ray;if(input){const xr=this.el.renderer?.xr,frame=xr?.getFrame?.()||eventFrame;let pose;try{pose=frame?.getPose(input.targetRaySpace,xr?.getReferenceSpace?.())}catch{}if(!pose)return null;const parent=source.object3D.parent||this.el.object3D;parent.updateWorldMatrix(true,false);const m=new T.Matrix4().fromArray(pose.transform.matrix).premultiply(parent.matrixWorld);ray=new T.Ray(new T.Vector3().setFromMatrixPosition(m),new T.Vector3(0,0,-1).transformDirection(m))}if(!ray)return null;el.object3D.updateWorldMatrix(true,true);return new T.Raycaster(ray.origin,ray.direction,0,20).intersectObject(el.object3D,true)[0]||null};canvas.down({detail:{intersection,cursorEl:{object3D:source.object3D,inputSource:input,components:{raycaster:{getIntersection}}}}})},
 nativeActivate(e){const input=e.inputSource,source=document.getElementById(input.handedness==='left'?'leftHand':'rightHand');if(!source)return;const k=key({detail:{cursorEl:source}}),prior=presses.get(k);if(prior?.down&&performance.now()-(prior.at||0)<120)return;window.GlobiquestPanelInput.release(source);const reference=this.el.renderer?.xr?.getReferenceSpace?.();let pose;try{pose=e.frame?.getPose(input.targetRaySpace,reference)}catch{}if(!pose)return;const parent=source.object3D.parent||this.el.object3D;parent.updateWorldMatrix(true,false);const matrix=new T.Matrix4().fromArray(pose.transform.matrix).premultiply(parent.matrixWorld),ray=new T.Ray(new T.Vector3().setFromMatrixPosition(matrix),new T.Vector3(0,0,-1).transformDirection(matrix)),caster=new T.Raycaster(ray.origin,ray.direction,0,20);let best;for(const el of cards){if(el.isConnected===false)continue;let visible=true;for(let p=el.object3D;p;p=p.parent)if(!p.visible)visible=false;for(let p=el.__panelOwner?.object3D;p;p=p.parent)if(!p.visible)visible=false;if(!visible)continue;el.object3D.updateWorldMatrix(true,true);const intersection=caster.intersectObject(el.object3D,true)[0],hit=intersection?{el,intersection}:null;if(better(hit,best))best=hit}if(!best)return;const r=region(best.el,best.intersection);presses.set(k,{el:best.el,region:r,generation:best.el.__panelInput?.generation,used:true,down:true,at:performance.now()});if(r?.drag)window.globiquest.panelDraggerFor?.(best.el)?.start(source,null,best.el);else if(r?.draw)this.startDrawing(best.el,best.intersection,source,input,e.frame);else r?.action?.();hover(best)},
 remove(){pointerTool(this.drawingCanvas)?.up();this.nativeCleanup?.();this.listeners?.forEach(fn=>fn());presses.clear()},tick(){this.bindSession();for(const el of [...cards]){if(el.isConnected===false){cards.delete(el);continue}const meta=el.__panelInput;if(meta.overlay&&performance.now()-(meta.hoverAt||0)>150)meta.overlay.visible=false}for(const id of ['leftHand','rightHand']){const source=document.getElementById(id),side=id==='leftHand'?'left':'right',input=[...(this.el.renderer?.xr?.getSession?.()?.inputSources||[])].find(s=>s.handedness===side),ray=source?.components?.raycaster?.raycaster?.ray;if(input?.hand||!ray)continue;let best;const caster=new T.Raycaster(ray.origin,ray.direction,0,20);for(const el of cards){let visible=true;for(let p=el.object3D;p;p=p.parent)if(!p.visible)visible=false;if(!visible)continue;el.object3D.updateWorldMatrix(true,true);const intersection=caster.intersectObject(el.object3D,true)[0],hit=intersection?{el,intersection}:null;if(better(hit,best))best=hit}if(best)hover(best)}}});
